function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 20) return 's needs 1 to 20 characters.';
  if (!/^[A-Za-z0-9+\-.]+$/.test(s)) return 's may only hold letters, digits, +, - and dots.';
  return null;
}

