      if (seenExp || !seenDigit) {
        return false;
      }
      seenExp = true;
      seenDigit = false;
    } else if (ch === '.') {
      if (seenDot || seenExp) {
        return false;
      }
      seenDot = true;
    } else {
      return false;
    }
  }
