function isNumber(s) {
  const mantissa = '[+-]?([0-9]+\\.?[0-9]*|\\.[0-9]+)';
  const exponent = '([eE][+-]?[0-9]+)?';
  return new RegExp('^' + mantissa + exponent + '$').test(s);
}

