function generate(rand, size) {
  const pick = (chars) => chars[Math.floor(rand() * chars.length)];
  const most = size === 'large' ? 8 : 3;
  const digits = (min) => {
    const count = min + Math.floor(rand() * (most - min + 1));
    let out = '';
    for (let i = 0; i < count; i++) out += pick('0123456789');
    return out;
  };
  const valid = () => {
    let text = rand() < 0.4 ? pick('+-') : '';
    const form = Math.floor(rand() * 3);
    if (form === 0) text += digits(1);
    else if (form === 1) text += digits(1) + '.' + digits(0);
    else text += '.' + digits(1);
    if (rand() < 0.5) text += pick('eE') + (rand() < 0.4 ? pick('+-') : '') + digits(1);
    return text;
  };
  for (;;) {
    let s;
    const mode = rand();
    if (mode < 0.4) {
      s = valid();
    } else if (mode < 0.8) {
      // Damage a valid number by one insertion, deletion or replacement.
      const chars = valid().split('');
      const at = Math.floor(rand() * chars.length);
      const ch = pick('0123456789+-.eE.+-eEaZ');
      const op = Math.floor(rand() * 3);
      if (op === 0) chars.splice(at, 0, ch);
      else if (op === 1) chars.splice(at, 1);
      else chars[at] = ch;
      s = chars.join('');
    } else {
      const length = 1 + Math.floor(rand() * (size === 'large' ? 20 : 6));
      s = '';
      for (let i = 0; i < length; i++) s += pick('0123456789+-.eE+-.eEx');
    }
    if (s.length >= 1 && s.length <= 20) return [s];
  }
}
